export const defaults={name:'แผนตัวอย่าง',age:35,retire:60,end:85,income:80000,expense:30000,debtPay:15000,premium:60000,cash:180000,invest:500000,other:2500000,debt:1800000,months:6,cover:1500000,supportYears:10,family:20000,education:500000,legacyAsset:0,goals:[{name:'เงินเพื่อการศึกษาลูก',target:1000000,years:10,fund:100000,monthly:4000}],retireFund:400000,retireSave:10000,retireExpense:30000,pension:5000,inflation:2.5,growth:5,postGrowth:3};
export function future(p,r,n,pmt=0){const m=Math.pow(1+r/100,1/12)-1,k=Math.round(n*12);return p*Math.pow(1+m,k)+pmt*(Math.abs(m)<1e-10?k:(Math.pow(1+m,k)-1)/m)}
export function saving(target,p,r,n){if(n<=0)return Math.max(0,target-p);const m=Math.pow(1+r/100,1/12)-1,k=Math.round(n*12);return Math.max(0,(target-future(p,r,n))/(Math.abs(m)<1e-10?k:(Math.pow(1+m,k)-1)/m))}
export function calculate(s){const living=s.expense+s.debtPay+s.premium/12,free=s.income-living,emergency=living*s.months,need=Math.max(0,s.family*12*s.supportYears+s.debt+s.education-s.legacyAsset),years=s.retire-s.age,spend=s.retireExpense*Math.pow(1+s.inflation/100,years);let target=0;for(let i=0;i<s.end-s.retire;i++)target+=Math.max(0,spend*12*Math.pow(1+s.inflation/100,i)-s.pension*12)/Math.pow(1+s.postGrowth/100,i);const retireFV=future(s.retireFund,s.growth,years,s.retireSave),goals=s.goals.map(g=>({...g,fv:future(g.fund,s.growth,g.years,g.monthly),required:saving(g.target,g.fund,s.growth,g.years)})),goalSave=goals.reduce((a,g)=>a+g.monthly,0),goalFund=goals.reduce((a,g)=>a+g.fund,0);return{living,free,emergency,emergencyGap:Math.max(0,emergency-s.cash),runway:living?s.cash/living:0,net:s.cash+s.invest+s.other-s.debt,need,coverGap:Math.max(0,need-s.cover),years,spend,target,retireFV,retireNeed:saving(target,s.retireFund,s.growth,years),goals,goalSave,goalFund,goalNeed:goals.reduce((a,g)=>a+g.required,0),remaining:free-goalSave-s.retireSave,unallocated:s.invest-goalFund-s.retireFund}}
export function validate(s){const errors=[];for(const [k,v]of Object.entries(defaults)){if(typeof v==='number'&&(!Number.isFinite(s[k])||s[k]<0||s[k]>1e12))errors.push('ตรวจสอบตัวเลข: '+k)}if(s.age>=s.retire||s.retire>=s.end||s.end>120)errors.push('อายุปัจจุบันต้องน้อยกว่าอายุเกษียณ และอายุสิ้นสุดแผน (ไม่เกิน 120 ปี)');if(!Array.isArray(s.goals))errors.push('ข้อมูลเป้าหมายไม่ถูกต้อง');else s.goals.forEach((g,i)=>{if(!g||typeof g.name!=='string'||!g.name.trim()||g.name.length>80){errors.push('กรุณาระบุชื่อเป้าหมายที่ '+(i+1));return}if(['target','years','fund','monthly'].some(k=>!Number.isFinite(g[k])||g[k]<0||g[k]>1e12))errors.push('ตรวจสอบตัวเลขเป้าหมายที่ '+(i+1));if(g.years<1||g.years>80)errors.push('ระยะเวลาเป้าหมายที่ '+(i+1)+' ต้องอยู่ระหว่าง 1–80 ปี')});if(s.growth>30||s.postGrowth>30||s.inflation>30)errors.push('สมมติฐานอัตราร้อยละต้องไม่เกิน 30%');if(s.legacyAsset>s.other)errors.push('สินทรัพย์ที่จัดสรรให้ครอบครัวต้องไม่เกินสินทรัพย์อื่น');return errors}

export function decodePlan(payload){
 if(!payload||payload.app!=='FP'||![1,2].includes(payload.version)||!payload.data)throw Error('รูปแบบไฟล์ไม่ใช่แผน FP ที่รองรับ');
 const raw=payload.data,next={};
 for(const[k,v]of Object.entries(defaults)){if(k==='goals')continue;if(typeof raw[k]!==typeof v)throw Error('ข้อมูลแผนไม่ครบหรือชนิดข้อมูลไม่ถูกต้อง');next[k]=raw[k];if(typeof v==='string'&&raw[k].length>80)throw Error('ข้อความในแผนยาวเกินกำหนด')}
 next.goals=payload.version===1?[{name:raw.goalName,target:raw.goal,years:raw.goalYears,fund:raw.goalFund,monthly:raw.goalSave}]:raw.goals;
 const errors=validate(next);if(errors.length)throw Error(errors.join(' • '));
 next.goals=next.goals.map(({name,target,years,fund,monthly})=>({name,target,years,fund,monthly}));return next;
}

export function planWarnings(s){
 const total=s.goals.reduce((a,g)=>a+g.fund,0)+s.retireFund;
 return total>s.invest?[`เงินตั้งต้นที่จัดสรรเกินสินทรัพย์ลงทุน ${(total-s.invest).toLocaleString('th-TH')} บาท — ผลเป้าหมายและเกษียณเป็นการจำลองที่ยังมีเงินไม่ครบ กรุณาลดเงินตั้งต้น หรือแก้สินทรัพย์ลงทุนในเมนูข้อมูลการเงินให้ตรงกับยอดจริง`]:[];
}
